ccc;border-radius:6px;padding:5px 9px;font-size:12px;pointer-events:none;max-width:200px;z-index:10;&quot;&gt;



const NODES=[{&quot;id&quot;: &quot;The Starfall Universe&quot;, &quot;color&quot;: &quot;#94a3b8&quot;, &quot;group&quot;: &quot;Other&quot;, &quot;links&quot;: 0}];
const EDGES=[];
const canvas=document.getElementById(&#039;gc&#039;);
const DPR=window.devicePixelRatio||1;
const W=canvas.parentElement.offsetWidth||680,H=600;
canvas.width=W*DPR;canvas.height=H*DPR;
canvas.style.width=W+&#039;px&#039;;canvas.style.height=H+&#039;px&#039;;
const ctx=canvas.getContext(&#039;2d&#039;);ctx.scale(DPR,DPR);
const nm={};
const nodes=NODES.map(n&lt;span&gt;&amp;rArr;&lt;/span&gt;{const o={...n,x:W/2+(Math.random()-.5)*400,y:H/2+(Math.random()-.5)*400,vx:0,vy:0};nm[n.id]=o;return o;});
let ag=&#039;all&#039;,st=&#039;&#039;,hl=null,tx=0,ty=0,tk=1,drag=null,doff={x:0,y:0},pan=false,ps={x:0,y:0},po={x:0,y:0},settled=false,iter=0,cs=null;
function nr(n){return Math.max(4,Math.min(13,3+n.links*0.55));}
function vis(){return nodes.filter(n&lt;span&gt;&amp;rArr;&lt;/span&gt;{if(ag!&lt;span class=&quot;text-highlight&quot;&gt;&#039;all&#039;&amp;&amp;n.group!&lt;/span&gt;ag)return false;if(st&amp;&amp;!n.id.toLowerCase().includes(st.toLowerCase()))return false;return true;});}
function tick(){if(settled)return;const vn=vis();const vs=new Set(vn.map(n&lt;span&gt;&amp;rArr;&lt;/span&gt;n.id));const al=Math.max(0.01,0.6-iter*0.004);vn.forEach(a&lt;span&gt;&amp;rArr;&lt;/span&gt;{a.vx+=(W/2-a.x)*0.015*al;a.vy+=(H/2-a.y)*0.015*al;});for(let i=0;i&lt;vn.length;i++){for(let j=i+1;j&lt;vn.length;j++){const a=vn[i],b=vn[j];let dx=a.x-b.x,dy=a.y-b.y,d2=dx*dx+dy*dy,d=Math.sqrt(d2)||0.1,rep=Math.min(800,120*120/d2);a.vx+=dx/d*rep*al;a.vy+=dy/d*rep*al;b.vx-=dx/d*rep*al;b.vy-=dy/d*rep*al;}}EDGES.forEach(e&lt;span&gt;&amp;rArr;&lt;/span&gt;{const a=nm[e.source],b=nm[e.target];if(!a||!b||!vs.has(e.source)||!vs.has(e.target))return;let dx=b.x-a.x,dy=b.y-a.y,d=Math.sqrt(dx*dx+dy*dy)||0.1,f=(d-70)*0.06*al;a.vx+=dx/d*f;a.vy+=dy/d*f;b.vx-=dx/d*f;b.vy-=dy/d*f;});let mv=0;vn.forEach(n&lt;span&gt;&amp;rArr;&lt;/span&gt;{n.vx*=0.75;n.vy*=0.75;n.x+=n.vx;n.y+=n.vy;n.x=Math.max(20,Math.min(W-20,n.x));n.y=Math.max(20,Math.min(H-20,n.y));mv=Math.max(mv,Math.abs(n.vx)+Math.abs(n.vy));});iter++;if(mv&lt;0.3&amp;&amp;iter&gt;60)settled=true;}
function draw(){ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(tx,ty);ctx.scale(tk,tk);const vn=vis();const vs=new Set(vn.map(n&lt;span&gt;&amp;rArr;&lt;/span&gt;n.id));const nb=new Set();if(hl){EDGES.forEach(e&lt;span&gt;&amp;rArr;&lt;/span&gt;{if(e.source=&lt;span class=&quot;text-highlight&quot;&gt;hl)nb.add(e.target);if(e.target&lt;/span&gt;=hl)nb.add(e.source);})}ctx.lineWidth=0.7;EDGES.forEach(e&lt;span&gt;&amp;rArr;&lt;/span&gt;{const a=nm[e.source],b=nm[e.target];if(!a||!b||!vs.has(e.source)||!vs.has(e.target))return;ctx.globalAlpha=(!hl||(hl=&lt;span class=&quot;text-highlight&quot;&gt;e.source||hl&lt;/span&gt;=e.target))?0.2:0.03;ctx.strokeStyle=&#039;#94a3b8&#039;;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();});vn.forEach(n&lt;span&gt;&amp;rArr;&lt;/span&gt;{const ih=hl===n.id,inn=nb.has(n.id);ctx.globalAlpha=!hl||ih||inn?1:0.12;ctx.beginPath();ctx.arc(n.x,n.y,nr(n),0,Math.PI*2);ctx.fillStyle=n.color;ctx.fill();if(ih){ctx.strokeStyle=&#039;rgba(255,255,255,0.9)&#039;;ctx.lineWidth=2;ctx.stroke();ctx.lineWidth=0.7;}});ctx.globalAlpha=1;ctx.font=`${Math.max(9,10/tk)}px sans-serif`;ctx.fillStyle=&#039;rgba(30,30,30,0.85)&#039;;vn.forEach(n&lt;span&gt;&amp;rArr;&lt;/span&gt;{const ih=hl===n.id,inn=nb.has(n.id);if(n.links&lt;span&gt;&amp;lArr;&lt;/span&gt;9&amp;&amp;!ih&amp;&amp;!inn)return;ctx.globalAlpha=!hl||ih||inn?1:0.12;ctx.fillText(n.id,n.x+nr(n)+2,n.y+4);});ctx.restore();}
function loop(){tick();draw();requestAnimationFrame(loop);}loop();
function cxy(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};}
function hit(cx,cy){const wx=(cx-tx)/tk,wy=(cy-ty)/tk;const vn=vis();for(let i=vn.length-1;i&gt;=0;i--){const n=vn[i];if(Math.hypot(n.x-wx,n.y-wy)&lt;nr(n)+5)return n;}return null;}
canvas.addEventListener(&#039;mousedown&#039;,e&lt;span&gt;&amp;rArr;&lt;/span&gt;{const{x,y}=cxy(e);cs={x,y};const n=hit(x,y);if(n){drag=n;doff={x:(x-tx)/tk-n.x,y:(y-ty)/tk-n.y};canvas.style.cursor=&#039;grabbing&#039;;}else{pan=true;ps={x,y};po={x:tx,y:ty};canvas.style.cursor=&#039;grabbing&#039;;}});
canvas.addEventListener(&#039;mousemove&#039;,e&lt;span&gt;&amp;rArr;&lt;/span&gt;{const{x,y}=cxy(e);if(drag){drag.x=(x-tx)/tk-doff.x;drag.y=(y-ty)/tk-doff.y;drag.vx=0;drag.vy=0;settled=false;}else if(pan){tx=po.x+(x-ps.x);ty=po.y+(y-ps.y);}else{const n=hit(x,y);const tip=document.getElementById(&#039;tip&#039;);if(n){tip.style.display=&#039;block&#039;;tip.style.left=(x+12)+&#039;px&#039;;tip.style.top=(y-10)+&#039;px&#039;;tip.innerHTML=`&lt;strong&gt;${n.id}&lt;/strong&gt;&lt;br&gt;&lt;span style=&quot;color:#888&quot;&gt;${n.group} · ${n.links} links&lt;/span&gt;`;canvas.style.cursor=&#039;pointer&#039;;}else{tip.style.display=&#039;none&#039;;canvas.style.cursor=&#039;grab&#039;;}}});
canvas.addEventListener(&#039;mouseup&#039;,e&lt;span&gt;&amp;rArr;&lt;/span&gt;{const{x,y}=cxy(e);if(drag&amp;&amp;cs&amp;&amp;Math.hypot(x-cs.x,y-cs.y)&lt;5){hl=hl===drag.id:drag.id;}drag=null;pan=false;canvas.style.cursor=&#039;grab&#039;;document.getElementById(&#039;tip&#039;).style.display=&#039;none&#039;;});
canvas.addEventListener(&#039;wheel&#039;,e&lt;span&gt;&amp;rArr;&lt;/span&gt;{e.preventDefault();const{x,y}=cxy(e);const f=e.deltaY&lt;0?1.12:0.89;tx=x-(x-tx)*f;ty=y-(y-ty)*f;tk=Math.max(0.15,Math.min(6,tk*f));},({passive:false}));
document.getElementById(&#039;btn-rst&#039;).onclick=()&lt;span&gt;&amp;rArr;&lt;/span&gt;{tx=0;ty=0;tk=1;hl=null;nodes.forEach(n&lt;span&gt;&amp;rArr;&lt;/span&gt;{n.x=W/2+(Math.random()-.5)*400;n.y=H/2+(Math.random()-.5)*400;n.vx=0;n.vy=0;});settled=false;iter=0;};
document.getElementById(&#039;fg&#039;).addEventListener(&#039;change&#039;,e&lt;span&gt;&amp;rArr;&lt;/span&gt;{ag=e.target.value;hl=null;settled=false;iter=0;});
document.getElementById(&#039;sq&#039;).addEventListener(&#039;input&#039;,e&lt;span&gt;&amp;rArr;&lt;/span&gt;{st=e.target.value;hl=null;settled=false;iter=0;});
